void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	//所用产生式：右部为空说明这一步不是推导而是终结符匹配
	ostringstream action;
	if (!rule_temp.right.empty()) {
		action << rule_temp;
	}
	else if (rule_temp.left != 0) {
		action << "“" << rule_temp.left << "”匹配";
	}
	cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
}
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
	stack<char> input_s;
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}

	//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
	bool success = true;
	if (table.row.empty()) {
		cout << "没有可用的文法规则，无法进行语法分析" << endl;
		success = false;
	}

	//分析过程表头
	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;

	//表驱动的分析过程：栈顶是非终结符就查表展开，是终结符就与当前输入符号匹配
	rule rule_temp;//本步骤所用的产生式，右部为空表示该步骤只是一次终结符匹配
	rule_temp.left = 0;
	unsigned int step = 0;
	while (success) {
		char top = analysis_s.top();
		char cur = input_s.top();
		if (top == '#' && cur == '#') {
			//分析栈与输入串同时到达结束标志，分析成功结束
			rule_temp.left = 0;
			rule_temp.right.clear();
			print_state(analysis_s, input_s, rule_temp);
			break;
		}
		if (++step > 10000) {
			cout << "推导步骤过多，文法可能存在左递归，分析终止" << endl;
			success = false;
			break;
		}
		vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), top);
		if (row_it == table.row.end()) {
			//栈顶是终结符：与当前输入符号相同才能一起弹出，否则分析失败
			if (top != cur) {
				cout << "栈顶终结符" << top << "与当前输入符号" << cur << "不匹配，分析终止" << endl;
				success = false;
